/// App-wide sound effects and music with persisted toggles.
///
/// Files live in assets/audio/. All SFX are short WAVs generated by
/// tools/gen_cq_audio2.py. Repeatable effects ship as three round-robin
/// takes. Music plays only inside a game (see [claimMusic]): Coin Quest has
/// [trackQuest], When Pigs Fly [trackPigs], the cabinet games [trackLevel].
class Audio extends ChangeNotifier with WidgetsBindingObserver {
  static final Audio instance = Audio._();
  Audio._();

  bool _sfx = true;
  bool _music = true;
  bool _ready = false;
  bool _musicPlaying = false;
  SharedPreferences? _prefs;

  bool get sfx => _sfx;
  bool get music => _music;

