  static const _coreFiles = [
    'tap_1.wav', 'swap_1.wav', 'invalid_1.wav', 'ting.wav',
    'coins_pour.wav', 'coin_flip_1.wav', 'win.wav',
  ];
  Future<void> init() async {
    if (_ready) return;
    _prefs = await SharedPreferences.getInstance();
    _sfx = _prefs!.getBool('audio.sfx') ?? true;
    _music = _prefs!.getBool('audio.music') ?? true;
    WidgetsBinding.instance.addObserver(this);
    try {
      FlameAudio.bgm.initialize();
      // The bed mixes rather than taking focus, same as the effects. Otherwise
      // every track change asks for and abandons audio focus, which is both
      // rude to whatever else is playing and visible as a stutter.
      await FlameAudio.bgm.audioPlayer.setAudioContext(_sfxContext);
    } catch (e) {
      debugPrint('audio init: $e');
    }
    _ready = true;
    notifyListeners();
    if (_music) startMusic();
    // Warm the players off the critical path. Web: only the handful every
    // screen shares, so first paint isn't waiting on 50 network fetches.
    // Native: assets are local, so build the lot.
    unawaited(_warm(kIsWeb ? _coreFiles : _sfxFiles));
  }

  // ---------------------------------------------------------------- sfx
  //
  // One persistent player per sound file, built on first use and kept for the
  // life of the app.
  //
  // The obvious call — FlameAudio.play(name) — is a trap on Android. Every
  // call constructs a fresh AudioPlayer, registers it with the plugin, and
  // appends it to the SoundPool's per-URL player list. Nothing ever takes it
  // back down: low-latency playback has no completion callback, so the
  // ReleaseMode.release that was supposed to clean up never fires. A few
  // minutes of cascades leaves hundreds of live players behind, each one more
  // work on every subsequent sample load, until effects drag and then go
  // silent for good. That was the "audio lags then stops" bug.
  //
  // Holding one player per file instead bounds the count at _sfxFiles.length,
  // loads each sample into the SoundPool exactly once, and reduces a replay to
  // two cheap platform calls.

  /// Memoised per-file players. Futures, not players, so two calls racing on
  /// the same sound can't build two of them.
  final Map<String, Future<AudioPlayer?>> _players = {};

  /// Effects mix with whatever else the device is playing. A 200 ms coin pop
  /// has no business grabbing audio focus, and asking for it per effect is
  /// what filled logcat with focus churn.
  static final AudioContext _sfxContext =
      AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build();

  Future<AudioPlayer?> _playerFor(String name) =>
      _players.putIfAbsent(name, () => _createPlayer(name));

  Future<AudioPlayer?> _createPlayer(String name) async {
    try {
      final p = AudioPlayer()..audioCache = FlameAudio.audioCache;
      await p.setPlayerMode(PlayerMode.lowLatency);
      await p.setAudioContext(_sfxContext);
      // stop, not release: release would unload the sample from the SoundPool
      // and we would pay the load cost again on the next hit.
      await p.setReleaseMode(ReleaseMode.stop);
      await p.setSource(AssetSource(name));
      return p;
    } catch (e) {
      debugPrint('sfx load $name: $e');
      return null;
    }
  }

  /// Builds every player once, in sequence, so the first hit of each sound is
  /// as prompt as the rest. Sequential on purpose — firing 50 source loads at
  /// the platform channel at once is its own stall.
  Future<void> _warm(List<String> files) async {
    for (final f in files) {
      await _playerFor(f);
    }
  }

  /// Round-robin cursor per sound family, so a long cascade doesn't fire the
  /// identical sample twelve times.
  final Map<String, int> _rrCursor = {};

  /// When each family last played, for the limiter below.
  final Map<String, int> _lastPlayed = {};

  /// Rolling window of recent voice starts.
  final List<int> _recentVoices = [];

  /// The SoundPool carries 32 streams. This ceiling is about taste, not
  /// capacity — it keeps a deep cascade percussive instead of muddy.
  static const _maxVoicesPerHalfSecond = 12;

  // ------------------------------------------------------- instrumentation
  //
  // The original bug was effects lagging and then stopping outright, which is
  // a failure nobody notices until it has already happened. These counters
  // make it measurable: a leak of the old kind shows as latency climbing run
  // over run long before anything goes silent, so the last-decile latency
  // against the first is the number that matters, not the totals.
  //
  // Reading them costs nothing when unused; the soak screen in the DEV build
  // is the only consumer.

  int sfxAttempts = 0, sfxPlayed = 0, sfxFailed = 0, sfxLimited = 0;

  /// Milliseconds from asking for a sound to the platform accepting it.
  /// Capped so a long session cannot grow this without bound.
  final List<int> sfxLatencies = [];
  static const _maxLatencySamples = 20000;

  void resetStats() {
    sfxAttempts = sfxPlayed = sfxFailed = sfxLimited = 0;
    sfxLatencies.clear();
  }

  void play(String name, {double volume = 1.0, int minGapMs = 0}) {
    if (!_sfx || !_ready) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    // Per-sound spacing: a rapid repeat of the same sample is what turns a
    // cascade into mush, so drop it rather than stack it.
    if (minGapMs > 0 && now - (_lastPlayed[name] ?? 0) < minGapMs) {
      sfxLimited++;
      return;
    }
    // Global voice ceiling over a short window.
    _recentVoices.removeWhere((ts) => now - ts > 500);
    if (_recentVoices.length >= _maxVoicesPerHalfSecond) {
      sfxLimited++;
      return;
    }
    _lastPlayed[name] = now;
    _recentVoices.add(now);
    sfxAttempts++;
    unawaited(_fire(name, volume));
  }

  Future<void> _fire(String name, double volume) async {
    final sw = Stopwatch()..start();
    try {
      final p = await _playerFor(name);
      if (p == null || !_sfx) return;
      // Volume is read when the stream starts, so it has to be set first.
      await p.setVolume(volume);
      // stop() clears the SoundPool stream id, which is what makes the
      // following call start the sample from the top rather than try to resume
      // a stream that already finished.
      await p.stop();
      await p.resume();
      sfxPlayed++;
      if (sfxLatencies.length < _maxLatencySamples) {
        sfxLatencies.add(sw.elapsedMilliseconds);
      }
    } catch (e) {
      sfxFailed++;
      debugPrint('sfx $name: $e');
    }
  }

  /// Every effect the soak can draw from.
  List<String> get allSfx => List.unmodifiable(_sfxFiles);

  /// Plays the next take of a round-robin family, e.g. `pop3_` -> pop3_2.wav.
  void _rr(String family, int takes, {double volume = 1.0, int minGapMs = 0}) {
    final i = ((_rrCursor[family] ?? 0) % takes) + 1;
    _rrCursor[family] = i;
    play('$family$i.wav', volume: volume, minGapMs: minGapMs);
  }

  void tap() => _rr('tap_', 3, volume: 0.6, minGapMs: 40);
  void swap() => _rr('swap_', 3, volume: 0.7, minGapMs: 40);
  void invalid() => _rr('invalid_', 3, volume: 0.8, minGapMs: 80);

  /// Pop pitch and tail both rise with cascade depth (1..5).
  void pop(int depth) => _rr('pop${depth.clamp(1, 5)}_', 3, volume: 0.8, minGapMs: 45);
  void land() => _rr('land_', 3, volume: 0.5, minGapMs: 60);
