  void win() => play('win.wav');
  void lose() => play('lose.wav', volume: 0.9);
  void star(int n) => play('star${n.clamp(1, 3)}.wav', volume: 0.9);
  // `payout()` and its sample are gone: nothing called it, and shipping a file
